// Färdigskrivna barnförklaringar, sv/en/fr/ar.
export const KIDS: Record<string, Record<string, string[]>> = {"sv":{"c:Aktie":["🍕 Tänk dig ett företag som en stor pizza.","✂️ Företaget delar pizzan i jättemånga små bitar. Varje bit kallas en aktie.","🙋 Köper du en aktie äger du en liten bit av företaget. Du blir delägare!","📈 Går företaget bra blir bitarna mer värda. Ibland delar företaget också ut en del av vinsten, det kallas utdelning.","🧠 Minnesregel: en aktie = en liten bit av ett företag."],"c:Börsen":["🏪 Börsen är som en jättestor marknad, fast man köper och säljer aktier i stället för frukt.","🙋‍♀️🙋 Där finns människor som vill köpa och människor som vill sälja.","🍦 Vill många ha samma glass men det finns få, går priset upp. Vill få ha den, går priset ner.","📈 Precis så är det med aktier: fler som vill köpa än sälja gör att priset stiger.","🧠 Minnesregel: många köpare = priset upp, många säljare = priset ner."],"c:Trading eller investering":["🌳 En investerare är som någon som planterar ett träd och väntar i många år på att det ska växa.","🏃 En trader är mer som en springare. Hen köper och säljer snabbt, ibland samma dag.","⏱️ Tradern försöker tjäna på att priset rör sig lite upp och ner under kort tid.","⚠️ Snabbt är inte lättare. De flesta som tradar ofta förlorar pengar.","🧠 Minnesregel: investerare = lång tid, trader = kort tid."],"c:Bid och ask":["🛒 Tänk dig att du vill sälja din cykel.","🙋 En köpare säger: jag betalar högst 99 kr. Det kallas bid, köparens bud.","🙋‍♀️ En säljare säger: jag säljer för minst 100 kr. Det kallas ask, säljarens pris.","↔️ Gapet mellan 99 och 100 kr kallas spread. Det är lite som en avgift du betalar när du handlar.","🧠 Minnesregel: bid = köparens pris, ask = säljarens pris, spread = gapet."],"c:Marknadsorder":["⚡ En marknadsorder betyder: köp nu, direkt, vad det än kostar just nu.","🍬 Som att gå till godisdisken och säga: jag tar den, oavsett pris!","😬 Det går snabbt, men om det finns få säljare kan du få betala mer än du trodde.","🧠 Minnesregel: marknadsorder = snabbt, men priset är inte säkert."],"c:Limitorder":["🎯 En limitorder betyder: jag köper bara om priset är högst så här mycket.","🍭 Som att säga: jag köper klubban om den kostar 10 kr eller mindre, annars väntar jag.","✅ Du betalar aldrig mer än ditt pris.","⏳ Men går priset aldrig ner till ditt pris blir det ingen affär alls.","🧠 Minnesregel: limitorder = säkert pris, men kanske inget köp."],"c:Fyra priser per ljus":["🕯️ Ett ljus i grafen berättar vad som hände med priset under en tid, till exempel en dag.","1️⃣ Öppning: priset när dagen började.","2️⃣ Högsta: det högsta priset under dagen. 3️⃣ Lägsta: det lägsta priset.","4️⃣ Stängning: priset när dagen slutade.","🧠 Minnesregel: ett ljus = fyra priser, öppning, högsta, lägsta, stängning."],"c:Grönt och rött":["🕯️ Titta på den tjocka delen av ljuset. Den kallas kropp.","🟢 Grönt ljus: priset slutade högre än det började. Det gick upp.","🔴 Rött ljus: priset slutade lägre än det började. Det gick ner.","🧠 Minnesregel: grönt = upp, rött = ner, jämfört med när perioden började."],"c:Veken":["🕯️ De tunna strecken ovanför och under kroppen kallas vekar, som veken på ett riktigt ljus.","⬆️ Toppen av den övre veken är det högsta priset.","⬇️ Botten av den nedre veken är det lägsta priset.","🎈 Veken visar hur långt priset hann flyga iväg innan det kom tillbaka.","🧠 Minnesregel: vekar = högsta och lägsta pris."],"c:Tidsram":["⏰ Ett ljus kan visa en minut, en timme, en dag eller en vecka. Det kallas tidsram.","🔍 Det är som att zooma in och ut på en karta.","🌦️ En dag kan regna i en timme men ändå vara solig i stort. Priset kan också falla en timme men stiga den veckan.","🧠 Minnesregel: kolla alltid vilken tidsram du tittar på."],"c:Volym":["📊 Volym är hur många aktier som köptes och såldes. Den syns som staplar under grafen.","🎉 Stor volym är som ett fullsatt kalas: många är med.","🤫 Liten volym är som ett nästan tomt rum: bara några få är med.","💪 När priset rör sig och många är med betyder det oftast mer.","🧠 Minnesregel: hög volym = många är med och rörelsen väger tyngre."],"c:Upptrend":["🪜 En upptrend är som en trappa som går uppåt.","⛰️ Priset gör toppar och bottnar, som små berg och dalar.","⬆️ I en upptrend blir varje topp högre än förra toppen, och varje botten högre än förra botten.","🧠 Minnesregel: högre toppar och högre bottnar = upptrend."],"c:Nedtrend":["🛝 En nedtrend är som en trappa eller rutschkana som går nedåt.","⬇️ Varje topp blir lägre än förra toppen.","⬇️ Varje botten blir också lägre än förra botten.","🧠 Minnesregel: lägre toppar och lägre bottnar = nedtrend."],"c:Sidled":["🏓 Ibland går priset varken upp eller ner. Det studsar fram och tillbaka, som en pingisboll.","📏 Det studsar mellan ett golv och ett tak som ligger på ungefär samma ställe hela tiden.","😴 Det kallas sidled eller intervall. Ingen sida vinner.","🧠 Minnesregel: samma toppar och samma bottnar = sidled."],"c:Stöd":["🏀 Tänk dig en boll som studsar på golvet.","⬇️ Priset faller, men vid en viss nivå slutar det falla och studsar upp igen.","🛒 Det beror på att många köpare tycker att priset är billigt där och köper.","🟢 Den nivån kallas stöd. Den är som ett golv.","🧠 Minnesregel: stöd = golv där köpare kliver in."],"c:Motstånd":["🏠 Tänk dig en boll som du kastar upp i ett rum. Den slår i taket och faller ner.","⬆️ Priset stiger, men vid en viss nivå vänder det ner flera gånger.","💰 Där tycker många att priset är dyrt och säljer.","🔴 Den nivån kallas motstånd. Den är som ett tak.","🧠 Minnesregel: motstånd = tak där säljare tar över."],"c:Utbrott":["🚀 Ibland tar sig priset igenom taket. Det kallas utbrott.","🏢 Det är som att gå upp en våning i ett hus.","🔄 Det gamla taket blir nu golvet på den nya våningen. Gammalt motstånd kan bli nytt stöd.","⚠️ Men ibland är utbrottet falskt och priset ramlar tillbaka ner.","🧠 Minnesregel: genom taket, och taket kan bli golv."],"c:Kroppens storlek":["🕯️ Titta på hur lång den tjocka kroppen är.","🦸 Lång kropp: en sida var mycket starkare. Köparna om den är grön, säljarna om den är röd.","🤝 Kort kropp: köpare och säljare var ungefär lika starka. Som en dragkamp där repet knappt rör sig.","🧠 Minnesregel: lång kropp = stark sida, kort kropp = jämn kamp."],"c:Vekar betyder avvisning":["🎾 En lång veke är som en boll som studsar mot en vägg och kommer tillbaka.","⬇️ Lång nedre veke: priset åkte långt ner, men köpare sa nej och tryckte upp det igen.","⬆️ Lång övre veke: priset åkte långt upp, men säljare sa nej och tryckte ner det igen.","🧠 Minnesregel: lång veke = priset var där men blev bortskickat."],"c:Marubozu":["🕯️ En marubozu är ett ljus helt utan vekar. Bara en tjock kropp.","🟢 Grön marubozu: köparna bestämde hela tiden, från första sekunden till sista.","🔴 Röd marubozu: säljarna bestämde hela tiden.","🧠 Minnesregel: inga vekar = en sida hade full kontroll."],"c:Kontext":["☂️ Ett paraply betyder något annat när det regnar än när solen skiner.","🔨 Samma ljusform kan också betyda olika saker beroende på vad som hände innan.","⬇️ Efter en nedgång kallas formen hammare och kan betyda att priset vill vända upp.","⬆️ Efter en uppgång kallas samma form hängande man och är en varning.","🧠 Minnesregel: titta alltid på vad som hände före mönstret."],"c:Plats":["📍 Var mönstret dyker upp är viktigt.","🏀 Ett mönster vid ett golv (stöd) eller tak (motstånd) är som en boll som studsar mot väggen: där händer något.","🌫️ Ett mönster mitt i ingenstans betyder oftast mindre.","🧠 Minnesregel: mönster vid viktiga nivåer är mer intressanta."],"c:Bekräftelse":["⏳ Ett mönster är som en ledtråd, inte ett säkert svar.","👀 Därför väntar många på nästa ljus innan de gör något.","✅ Stänger nästa ljus över mönstrets högsta pris har mönstret uppåt fått stöd. Det kallas bekräftelse.","🧠 Minnesregel: vänta på nästa ljus innan du litar på mönstret."],"c:Ingång":["🚪 Ingång betyder när du köper och går in i affären.","⬆️ Efter ett mönster uppåt väntar många tills priset går över mönstrets högsta pris.","✅ Då har priset visat att det verkligen vill uppåt.","🧠 Minnesregel: gå in när priset bryter över mönstrets topp."],"c:Stop-loss":["🛑 En stop-loss är en nödbroms. Du bestämmer i förväg var du säljer om priset faller.","📉 Faller priset dit säljs aktierna automatiskt, så att förlusten inte blir större.","🦘 Obs: om priset hoppar förbi nivån, till exempel över natten, kan du få sälja lite lägre än du tänkt.","📍 Efter ett mönster läggs bromsen ofta strax under mönstrets lägsta pris. Går priset dit fungerade mönstret inte.","🧠 Minnesregel: ingen affär utan nödbroms."],"c:Mål":["🎯 Målet är var du tänker sälja med vinst.","⛰️ Ofta sätter man målet vid nästa tak, alltså nästa motstånd.","⚖️ Sedan jämför man: hur långt är det till målet, och hur långt till nödbromsen?","🧠 Minnesregel: målet ska vara längre bort än stoppen."],"c:Falska signaler":["🎣 Alla mönster fungerar inte. Ibland nappar fisken inte fast man gör allt rätt.","❌ Ett mönster kan se perfekt ut och ändå misslyckas.","🛑 Därför är små förluster och nödbroms viktigare än att hitta det perfekta mönstret.","🧠 Minnesregel: förlora lite när du har fel, så klarar du dig länge."],"c:Medelvärde":["🧮 Ett medelvärde är snittet. Lägg ihop priserna och dela med hur många de är.","🌡️ Som att räkna ut genomsnittstemperaturen för en vecka, i stället för att titta på varje dag.","〰️ Linjen blir mjuk och lugn och visar åt vilket håll priset går.","🔁 Den heter glidande för att den räknas om varje dag med de senaste dagarna.","🧠 Minnesregel: medelvärde = lugn linje som visar trenden."],"c:Pris och MA":["📈 Ligger priset över en medelvärdeslinje som pekar uppåt ser det positivt ut.","📉 Ligger priset under en linje som pekar nedåt ser det negativt ut.","🤔 Det är en ledtråd, inte ett löfte.","🧠 Minnesregel: över stigande linje = bra tecken, under fallande linje = dåligt tecken."],"c:RSI":["🏃 RSI är som en hastighetsmätare för priset. Den visar hur snabbt och starkt priset har rört sig.","🔢 Den går från 0 till 100.","🔥 Över 70 kallas överköpt: priset har sprungit väldigt fort uppåt.","🧊 Under 30 kallas översålt: priset har fallit väldigt fort.","🧠 Minnesregel: RSI över 70 = väldigt snabbt upp, under 30 = väldigt snabbt ner."],"c:Varning":["🏃‍♂️ En löpare som springer fort måste inte stanna direkt.","🔥 Överköpt betyder inte att priset måste falla nu.","💪 I starka trender kan RSI ligga högt länge.","🧠 Minnesregel: högt RSI = var vaksam, inte automatiskt sälj."],"c:1–2-procentsregeln":["🍬 Tänk dig att du har 100 godisbitar.","🎲 Om du bara satsar 1 eller 2 bitar per gång har du kvar massor även om du förlorar många gånger i rad.","💥 Satsar du 50 bitar räcker två förluster för att nästan allt är borta.","🧠 Minnesregel: riskera högst 1–2 procent av kontot per affär."],"c:Förluster är asymmetriska":["🍰 Du har en tårta. Om halva tårtan försvinner har du en halv tårta kvar.","➕ För att få en hel tårta igen måste den halva tårtan dubblas. Det är 100 procent mer!","📉 Att förlora 50 procent är alltså mycket lättare än att sedan vinna tillbaka det.","🧠 Minnesregel: skydda pengarna först, för det är svårt att ta igen stora förluster."],"c:Positionsstorlek":["❓ Positionsstorlek betyder: hur många aktier ska jag köpa?","💰 Först bestämmer du hur mycket du kan tänka dig att förlora, till exempel 100 kr.","📏 Sedan kollar du hur långt det är till nödbromsen, till exempel 2 kr per aktie.","➗ 100 kr delat med 2 kr = 50 aktier. Om bromsen löser ut förlorar du bara 100 kr.","🧠 Minnesregel: antal aktier = risk i kronor ÷ avstånd till stop-loss."],"c:Risk/reward":["⚖️ Risk/reward är en våg. På ena sidan: vad du kan förlora. På andra: vad du kan vinna.","🍬 Riskera 1 godisbit för att kunna vinna 3. Det skrivs 1:3.","✅ Då räcker det att ha rätt ungefär 1 gång av 4 för att gå jämnt, om man inte räknar avgifter.","🧠 Minnesregel: möjlig vinst ska vara större än möjlig förlust."],"c:FOMO":["😱 FOMO betyder rädslan att missa något.","🎢 Alla pratar om en aktie som har rusat, och du vill också hoppa på.","🏔️ Men då köper man ofta när priset redan är på toppen.","🧘 Det är bättre att följa sin plan. Det kommer alltid fler chanser.","🧠 Minnesregel: jaga inte, det kommer en ny buss."],"c:Hämndtrading":["😤 Hämndtrading är när man har förlorat och blir arg och vill vinna tillbaka direkt.","🎰 Då tar man större risker än vanligt, som att satsa allt på en gång.","📉 Det slutar ofta med en ännu större förlust.","🧠 Minnesregel: efter en förlust, ta en paus."],"c:Tradingplan":["🗺️ En tradingplan är som en karta innan en resa.","📝 Du skriver ner i förväg: vad du köper, när du köper, var nödbromsen ligger och hur mycket du riskerar.","🧊 Då bestämmer du med lugnt huvud i stället för när du är stressad.","🧠 Minnesregel: planera först, handla sedan."],"c:Avgifter":["🧾 Varje gång du köper eller säljer kostar det lite pengar. Det kallas courtage.","↔️ Spreaden, gapet mellan köp- och säljpris, kostar också.","🔁 Handlar du ofta blir alla små kostnader till en stor summa.","🧠 Minnesregel: fler affärer = mer avgifter."],"c:ISK":["🏦 ISK är en sorts sparkonto för aktier och fonder i Sverige.","🧾 Du betalar inte skatt varje gång du tjänar pengar. I stället betalar du en liten skatt varje år, beräknad på hur mycket du har på kontot.","🎁 Sedan 2026 är de första 300 000 kronorna skattefria, sammanlagt för en person. Reglerna kan ändras, så kolla Skatteverket.","🧠 Minnesregel: ISK = liten skatt per år i stället för skatt på varje vinst."],"c:Varningstecken":["🚨 Lovar någon att du garanterat blir rik snabbt? Då är det nästan alltid lurendrejeri.","⏰ Säger någon att du måste skynda dig nu? Det är ett knep för att du inte ska hinna tänka.","💬 Grupper i appar som vill att du skickar pengar till dem är ett vanligt bedrägeri.","🔍 Kolla alltid företaget hos Finansinspektionen.","🧠 Minnesregel: garanterat + bråttom = gå därifrån."],"p:doji":["🕯️ Titta på ljuset: kroppen är nästan bara ett streck.","🤝 Priset slutade nästan exakt där det började. Köpare och säljare drog lika mycket i repet.","⏸️ Efter en lång rörelse kan det betyda att kraften håller på att ta slut.","🧠 Minnesregel: doji = oavgjort, vänta på nästa ljus."],"p:dragonfly":["🪰 Ljuset ser ut som ett T, som en trollslända.","⬇️ Säljarna tryckte ner priset långt.","⬆️ Men köparna tryckte tillbaka hela vägen upp innan perioden var slut.","🧠 Minnesregel: trollsländan efter en nedgång kan betyda att köparna vaknar."],"p:gravestone":["🪦 Ljuset ser ut som ett upp-och-ner-T, som en gravsten.","⬆️ Köparna tryckte upp priset högt.","⬇️ Men säljarna tryckte ner det hela vägen tillbaka.","🧠 Minnesregel: gravstenen efter en uppgång är en varning för fall."],"p:longDoji":["🕯️ Titta: nästan ingen kropp, men väldigt långa vekar åt båda håll.","🎢 Priset åkte långt upp och långt ner, men slutade där det började.","🤷 Ingen vet vem som vinner. Stor osäkerhet.","🧠 Minnesregel: långa ben = stor förvirring, vänta och se."],"p:spinning":["🌀 En snurrtopp har en liten kropp i mitten och vekar åt båda håll.","🤝 Ingen sida tog kontroll den här perioden.","⏸️ Den dyker ofta upp när trenden tar en paus.","🧠 Minnesregel: snurrtopp = paus, vänta på nästa ljus."],"p:marubozuBull":["🟩 Ett långt grönt ljus helt utan vekar.","🦸 Köparna bestämde från första sekund till sista.","🚀 Det syns ofta i början av en uppgång.","🧠 Minnesregel: grön utan vekar = köparna har full kontroll."],"p:marubozuBear":["🟥 Ett långt rött ljus helt utan vekar.","🦹 Säljarna bestämde från första sekund till sista.","📉 Det syns ofta i början av en nedgång.","🧠 Minnesregel: röd utan vekar = säljarna har full kontroll."],"p:hammer":["🔨 Ljuset ser ut som en hammare: liten kropp uppe och ett långt skaft nedåt.","⬇️ Priset föll långt under perioden.","⬆️ Men köparna sa nej och tryckte upp det igen.","📍 Den är mest intressant efter en nedgång, vid ett golv.","🧠 Minnesregel: hammaren slår i botten, kanske vänder priset upp."],"p:invHammer":["🔨 En hammare upp och ner: liten kropp nere och lång veke uppåt.","⬆️ Efter en nedgång försökte köparna trycka upp priset.","🤔 De lyckades inte riktigt än, så man väntar på ett starkt grönt ljus efteråt.","🧠 Minnesregel: inverterad hammare = köparna testar, vänta på bekräftelse."],"p:hangingMan":["🧍 Den ser ut precis som hammaren, men dyker upp efter en uppgång.","⬇️ Under perioden lyckades säljarna få ner priset en bit.","⚠️ Det kan vara första tecknet på att uppgången är trött.","🧠 Minnesregel: samma form som hammaren, men på toppen = varning."],"p:shootingStar":["🌠 Ett stjärnfall: liten kropp nere och lång veke uppåt, efter en uppgång.","⬆️ Priset flög upp högt under perioden.","⬇️ Men säljarna tryckte ner det igen, som en stjärna som faller.","🧠 Minnesregel: stjärnfall på toppen = priset kan falla."],"p:bullEng":["🐟 Två ljus: först ett litet rött, sedan ett stort grönt.","🍽️ Det gröna är så stort att det slukar hela det röda, som en stor fisk som äter en liten.","💪 Köparna tog över efter säljarna.","🧠 Minnesregel: stor grön äter liten röd efter en nedgång = möjlig vändning upp."],"p:bearEng":["🐟 Två ljus: först ett litet grönt, sedan ett stort rött.","🍽️ Det röda slukar hela det gröna.","👎 Säljarna tog över efter köparna.","🧠 Minnesregel: stor röd äter liten grön efter en uppgång = möjlig vändning ner."],"p:piercing":["🔴 Först ett rött ljus.","🟢 Sedan ett grönt som börjar lägre, men klättrar upp förbi mitten av det röda.","🗡️ Det tränger igenom, därav namnet.","🧠 Minnesregel: grönt som når över halva det röda = köparna kommer tillbaka."],"p:darkCloud":["🟢 Först ett grönt ljus.","☁️ Sedan ett rött som börjar högre men faller ner under mitten av det gröna, som ett mörkt moln.","⚠️ Säljarna börjar ta över efter en uppgång.","🧠 Minnesregel: rött som faller under halva det gröna = moln på väg."],"p:bullHarami":["🤰 Harami betyder gravid på japanska.","🔴 Ett stort rött ljus, sedan ett litet grönt som ryms inuti det, som en bebis i en mage.","🐢 Säljarna har börjat tappa kraft.","🧠 Minnesregel: liten grön inuti stor röd = svag signal, vänta på bekräftelse."],"p:bearHarami":["🤰 Ett stort grönt ljus, sedan ett litet rött som ryms inuti det.","🐢 Köparna har börjat tappa kraft.","⚠️ Signalen är svag, så man väntar på nästa ljus.","🧠 Minnesregel: liten röd inuti stor grön = varning, vänta på bekräftelse."],"p:tweezBot":["🥢 Två ljus med exakt samma lägsta pris, som två pincettspetsar.","🛡️ Köparna försvarade samma golv två gånger.","🧠 Minnesregel: två bottnar på samma nivå = starkt golv."],"p:tweezTop":["🥢 Två ljus med exakt samma högsta pris.","🛡️ Säljarna försvarade samma tak två gånger.","🧠 Minnesregel: två toppar på samma nivå = starkt tak."],"p:morningStar":["🌅 Tre ljus, som när solen går upp.","🔴 Först ett stort rött: det är mörkt och priset faller.","⭐ Sedan ett litet ljus längre ner: det blir tyst och stilla.","🟢 Sist ett stort grönt som klättrar högt: solen går upp!","🧠 Minnesregel: morgonstjärna = natten är slut, priset kan vända upp."],"p:eveningStar":["🌇 Tre ljus, som när solen går ner.","🟢 Först ett stort grönt: dagen är ljus och priset stiger.","⭐ Sedan ett litet ljus längre upp: det blir stilla.","🔴 Sist ett stort rött som faller djupt: solen går ner.","🧠 Minnesregel: aftonstjärna = kvällen kommer, priset kan vända ner."],"p:soldiers":["💂💂💂 Tre stora gröna ljus i rad, som soldater som marscherar uppåt.","⬆️ Varje ljus slutar nära sin högsta punkt.","💪 Köparna är starka.","⚠️ Har priset redan stigit väldigt länge kan de vara trötta.","🧠 Minnesregel: tre gröna soldater = stark uppgång."],"p:crows":["🐦‍⬛🐦‍⬛🐦‍⬛ Tre stora röda ljus i rad, som kråkor som flyger nedåt.","⬇️ Varje ljus slutar nära sin lägsta punkt.","👎 Säljarna är starka.","🧠 Minnesregel: tre svarta kråkor = starkt fall."],"p:insideUp":["1️⃣ Ett stort rött ljus.","2️⃣ Ett litet grönt inuti det, det är en harami.","3️⃣ Ett tredje grönt ljus som stänger högre än där det första började. Det bekräftar!","🧠 Minnesregel: harami + bekräftelse = tre inifrån upp."],"p:insideDown":["1️⃣ Ett stort grönt ljus.","2️⃣ Ett litet rött inuti det, en harami.","3️⃣ Ett tredje rött som stänger lägre än där det första började. Bekräftat!","🧠 Minnesregel: harami + bekräftelse nedåt = tre inifrån ner."],"p:risingThree":["🟢 Först ett stort grönt ljus.","😮‍💨 Sedan tre små röda som håller sig inom det. Priset tar en paus, som en löpare som hämtar andan.","🚀 Sist ett nytt stort grönt som når en ny topp.","🧠 Minnesregel: paus i uppgången, sedan fortsätter den."],"p:fallingThree":["🔴 Först ett stort rött ljus.","😮‍💨 Sedan tre små gröna inom det. En kort paus.","📉 Sist ett nytt stort rött som når en ny botten.","🧠 Minnesregel: paus i nedgången, sedan fortsätter den."]},"en":{"c:Aktie":["🍕 Imagine a company is a big pizza.","✂️ The company cuts the pizza into lots of tiny slices. Each slice is called a share.","🙋 If you buy a share, you own a tiny piece of the company. You become an owner!","📈 If the company does well, the slices are worth more. Sometimes the company also hands out part of its profit, called a dividend.","🧠 Remember: a share = a tiny piece of a company."],"c:Börsen":["🏪 The stock exchange is like a giant market, but people buy and sell shares instead of fruit.","🙋‍♀️🙋 There are people who want to buy and people who want to sell.","🍦 If lots of kids want the same ice cream and there's only a little, the price goes up. If few want it, the price goes down.","📈 Shares work the same way: more people wanting to buy than sell makes the price rise.","🧠 Remember: many buyers = price up, many sellers = price down."],"c:Trading eller investering":["🌳 An investor is like someone who plants a tree and waits many years for it to grow.","🏃 A trader is more like a sprinter. They buy and sell quickly, sometimes on the same day.","⏱️ The trader tries to earn money from small price moves over a short time.","⚠️ Fast is not easier. Most people who trade often lose money.","🧠 Remember: investor = long time, trader = short time."],"c:Bid och ask":["🛒 Imagine you want to sell your bike.","🙋 A buyer says: I'll pay at most 99. That's called the bid, the buyer's offer.","🙋‍♀️ A seller says: I'll sell for at least 100. That's called the ask, the seller's price.","↔️ The gap between 99 and 100 is called the spread. It's a bit like a fee you pay when you trade.","🧠 Remember: bid = buyer's price, ask = seller's price, spread = the gap."],"c:Marknadsorder":["⚡ A market order means: buy now, right away, whatever it costs at this moment.","🍬 Like going to the candy counter and saying: I'll take it, whatever the price!","😬 It's fast, but if there are few sellers you might pay more than you expected.","🧠 Remember: market order = fast, but the price isn't certain."],"c:Limitorder":["🎯 A limit order means: I'll only buy if the price is at most this much.","🍭 Like saying: I'll buy the lollipop if it costs 10 or less, otherwise I'll wait.","✅ You never pay more than your price.","⏳ But if the price never drops to your price, there's no trade at all.","🧠 Remember: limit order = safe price, but maybe no purchase."],"c:Fyra priser per ljus":["🕯️ A candle on the chart tells you what happened to the price during a period, like one day.","1️⃣ Open: the price when the day started.","2️⃣ High: the highest price of the day. 3️⃣ Low: the lowest price.","4️⃣ Close: the price when the day ended.","🧠 Remember: one candle = four prices: open, high, low, close."],"c:Grönt och rött":["🕯️ Look at the thick part of the candle. It's called the body.","🟢 Green candle: the price ended higher than it started. It went up.","🔴 Red candle: the price ended lower than it started. It went down.","🧠 Remember: green = up, red = down, compared to the start of the period."],"c:Veken":["🕯️ The thin lines above and below the body are called wicks, like the wick on a real candle.","⬆️ The top of the upper wick is the highest price.","⬇️ The bottom of the lower wick is the lowest price.","🎈 The wick shows how far the price flew off before it came back.","🧠 Remember: wicks = highest and lowest price."],"c:Tidsram":["⏰ A candle can show one minute, one hour, one day or one week. That's called the timeframe.","🔍 It's like zooming in and out on a map.","🌦️ A day can have an hour of rain but still be sunny overall. A price can also fall for an hour but rise that week.","🧠 Remember: always check which timeframe you're looking at."],"c:Volym":["📊 Volume is how many shares were bought and sold. It shows as bars under the chart.","🎉 High volume is like a packed party: lots of people are there.","🤫 Low volume is like an almost empty room: only a few are there.","💪 When the price moves and lots of people are involved, it usually means more.","🧠 Remember: high volume = many are involved and the move counts more."],"c:Upptrend":["🪜 An uptrend is like stairs going up.","⛰️ The price makes peaks and dips, like little hills and valleys.","⬆️ In an uptrend each peak is higher than the last peak, and each dip is higher than the last dip.","🧠 Remember: higher highs and higher lows = uptrend."],"c:Nedtrend":["🛝 A downtrend is like stairs or a slide going down.","⬇️ Each peak is lower than the last peak.","⬇️ Each dip is also lower than the last dip.","🧠 Remember: lower highs and lower lows = downtrend."],"c:Sidled":["🏓 Sometimes the price goes neither up nor down. It bounces back and forth like a ping-pong ball.","📏 It bounces between a floor and a ceiling that stay in about the same place.","😴 That's called sideways or a range. Neither side wins.","🧠 Remember: same highs and same lows = sideways."],"c:Stöd":["🏀 Imagine a ball bouncing on the floor.","⬇️ The price falls, but at a certain level it stops falling and bounces back up.","🛒 That's because many buyers think the price is cheap there and buy.","🟢 That level is called support. It's like a floor.","🧠 Remember: support = a floor where buyers step in."],"c:Motstånd":["🏠 Imagine throwing a ball up in a room. It hits the ceiling and falls down.","⬆️ The price rises, but at a certain level it turns down again and again.","💰 There, many people think the price is expensive and sell.","🔴 That level is called resistance. It's like a ceiling.","🧠 Remember: resistance = a ceiling where sellers take over."],"c:Utbrott":["🚀 Sometimes the price breaks through the ceiling. That's called a breakout.","🏢 It's like going up one floor in a building.","🔄 The old ceiling now becomes the floor of the new level. Old resistance can become new support.","⚠️ But sometimes the breakout is fake and the price falls back down.","🧠 Remember: through the ceiling, and the ceiling can become the floor."],"c:Kroppens storlek":["🕯️ Look at how long the thick body is.","🦸 Long body: one side was much stronger. Buyers if it's green, sellers if it's red.","🤝 Short body: buyers and sellers were about equally strong. Like a tug-of-war where the rope barely moves.","🧠 Remember: long body = strong side, short body = even fight."],"c:Vekar betyder avvisning":["🎾 A long wick is like a ball bouncing off a wall and coming back.","⬇️ Long lower wick: the price went far down, but buyers said no and pushed it back up.","⬆️ Long upper wick: the price went far up, but sellers said no and pushed it back down.","🧠 Remember: long wick = the price got there but was sent away."],"c:Marubozu":["🕯️ A marubozu is a candle with no wicks at all. Just a thick body.","🟢 Green marubozu: buyers were in charge the whole time, from the first second to the last.","🔴 Red marubozu: sellers were in charge the whole time.","🧠 Remember: no wicks = one side had full control."],"c:Kontext":["☂️ An umbrella means something different when it's raining than when the sun is shining.","🔨 The same candle shape can also mean different things depending on what happened before.","⬇️ After a fall, the shape is called a hammer and can mean the price wants to turn up.","⬆️ After a rise, the same shape is called a hanging man and is a warning.","🧠 Remember: always look at what happened before the pattern."],"c:Plats":["📍 Where a pattern shows up matters.","🏀 A pattern at a floor (support) or ceiling (resistance) is like a ball hitting a wall: something happens there.","🌫️ A pattern in the middle of nowhere usually means less.","🧠 Remember: patterns at important levels are more interesting."],"c:Bekräftelse":["⏳ A pattern is like a clue, not a sure answer.","👀 That's why many people wait for the next candle before doing anything.","✅ If the next candle closes above the pattern's highest price, the up pattern has been backed up. That's called confirmation.","🧠 Remember: wait for the next candle before trusting the pattern."],"c:Ingång":["🚪 Entry means when you buy and step into the trade.","⬆️ After an up pattern, many wait until the price goes above the pattern's highest price.","✅ Then the price has shown that it really wants to go up.","🧠 Remember: enter when the price breaks above the pattern's top."],"c:Stop-loss":["🛑 A stop-loss is an emergency brake. You decide in advance where you'll sell if the price falls.","📉 If the price falls there, the shares are sold automatically, so the loss doesn't get bigger.","🦘 Note: if the price jumps past the level, for example overnight, you may sell a little lower than planned.","📍 After a pattern, the brake is often placed just below the pattern's lowest price. If the price gets there, the pattern didn't work.","🧠 Remember: no trade without an emergency brake."],"c:Mål":["🎯 The target is where you plan to sell for a profit.","⛰️ People often put the target at the next ceiling, the next resistance.","⚖️ Then you compare: how far is it to the target, and how far to the emergency brake?","🧠 Remember: the target should be further away than the stop."],"c:Falska signaler":["🎣 Not all patterns work. Sometimes the fish doesn't bite even though you do everything right.","❌ A pattern can look perfect and still fail.","🛑 That's why small losses and an emergency brake matter more than finding the perfect pattern.","🧠 Remember: lose a little when you're wrong, and you'll last a long time."],"c:Medelvärde":["🧮 An average is the middle value. Add the prices together and divide by how many there are.","🌡️ Like working out the average temperature for a week instead of looking at each day.","〰️ The line becomes smooth and calm and shows which way the price is going.","🔁 It's called moving because it's recalculated every day using the latest days.","🧠 Remember: moving average = a calm line that shows the trend."],"c:Pris och MA":["📈 If the price is above an average line that points up, it looks positive.","📉 If the price is below a line that points down, it looks negative.","🤔 It's a clue, not a promise.","🧠 Remember: above a rising line = good sign, below a falling line = bad sign."],"c:RSI":["🏃 RSI is like a speedometer for the price. It shows how fast and strongly the price has moved.","🔢 It goes from 0 to 100.","🔥 Above 70 is called overbought: the price has run up very fast.","🧊 Below 30 is called oversold: the price has fallen very fast.","🧠 Remember: RSI above 70 = very fast up, below 30 = very fast down."],"c:Varning":["🏃‍♂️ A runner going fast doesn't have to stop right away.","🔥 Overbought doesn't mean the price has to fall now.","💪 In strong trends, RSI can stay high for a long time.","🧠 Remember: high RSI = be careful, not an automatic sell."],"c:1–2-procentsregeln":["🍬 Imagine you have 100 candies.","🎲 If you only bet 1 or 2 candies each time, you still have lots left even if you lose many times in a row.","💥 If you bet 50 candies, two losses are enough for almost everything to be gone.","🧠 Remember: risk at most 1–2 percent of the account per trade."],"c:Förluster är asymmetriska":["🍰 You have a cake. If half the cake disappears, you have half a cake left.","➕ To get a whole cake again, the half cake has to double. That's 100 percent more!","📉 So losing 50 percent is much easier than winning it back afterwards.","🧠 Remember: protect your money first, because big losses are hard to win back."],"c:Positionsstorlek":["❓ Position size means: how many shares should I buy?","💰 First you decide how much you're willing to lose, for example 100.","📏 Then you check how far it is to the emergency brake, for example 2 per share.","➗ 100 divided by 2 = 50 shares. If the brake triggers, you only lose 100.","🧠 Remember: number of shares = risk in money ÷ distance to stop-loss."],"c:Risk/reward":["⚖️ Risk/reward is a scale. On one side: what you could lose. On the other: what you could win.","🍬 Risk 1 candy to be able to win 3. That's written 1:3.","✅ Then being right about 1 time in 4 is enough to break even, not counting fees.","🧠 Remember: the possible win should be bigger than the possible loss."],"c:FOMO":["😱 FOMO means the fear of missing out.","🎢 Everyone is talking about a share that has shot up, and you want to jump in too.","🏔️ But then people often buy when the price is already at the top.","🧘 It's better to follow your plan. There are always more chances.","🧠 Remember: don't chase, another bus will come."],"c:Hämndtrading":["😤 Revenge trading is when you've lost, get angry and want to win it back right away.","🎰 Then you take bigger risks than usual, like betting everything at once.","📉 It often ends with an even bigger loss.","🧠 Remember: after a loss, take a break."],"c:Tradingplan":["🗺️ A trading plan is like a map before a trip.","📝 You write down in advance: what you buy, when you buy, where the emergency brake is and how much you risk.","🧊 Then you decide with a calm head instead of when you're stressed.","🧠 Remember: plan first, trade later."],"c:Avgifter":["🧾 Every time you buy or sell, it costs a little money. That's called a commission or brokerage fee.","↔️ The spread, the gap between the buy and sell price, also costs.","🔁 If you trade often, all the small costs add up to a big amount.","🧠 Remember: more trades = more fees."],"c:ISK":["🏦 ISK is a kind of savings account for shares and funds in Sweden.","🧾 You don't pay tax every time you make money. Instead you pay a small tax each year, based on how much is in the account.","🎁 Since 2026, the first 300,000 kronor are tax-free, in total per person. Rules can change, so check with the Swedish Tax Agency.","🧠 Remember: ISK = a small yearly tax instead of tax on every profit."],"c:Varningstecken":["🚨 Is someone promising you'll definitely get rich fast? Then it's almost always a scam.","⏰ Is someone saying you must hurry now? That's a trick so you don't have time to think.","💬 Groups in apps that want you to send them money are a common scam.","🔍 Always check the company with the financial regulator.","🧠 Remember: guaranteed + hurry = walk away."],"p:doji":["🕯️ Look at the candle: the body is almost just a line.","🤝 The price ended almost exactly where it started. Buyers and sellers pulled the rope equally hard.","⏸️ After a long move, it can mean the energy is running out.","🧠 Remember: doji = a draw, wait for the next candle."],"p:dragonfly":["🪰 The candle looks like a T, like a dragonfly.","⬇️ Sellers pushed the price far down.","⬆️ But buyers pushed it all the way back up before the period ended.","🧠 Remember: a dragonfly after a fall can mean buyers are waking up."],"p:gravestone":["🪦 The candle looks like an upside-down T, like a gravestone.","⬆️ Buyers pushed the price up high.","⬇️ But sellers pushed it all the way back down.","🧠 Remember: a gravestone after a rise is a warning of a fall."],"p:longDoji":["🕯️ Look: almost no body, but very long wicks in both directions.","🎢 The price went far up and far down, but ended where it started.","🤷 Nobody knows who will win. Lots of uncertainty.","🧠 Remember: long legs = big confusion, wait and see."],"p:spinning":["🌀 A spinning top has a small body in the middle and wicks in both directions.","🤝 Neither side took control this period.","⏸️ It often shows up when the trend takes a break.","🧠 Remember: spinning top = pause, wait for the next candle."],"p:marubozuBull":["🟩 A long green candle with no wicks at all.","🦸 Buyers were in charge from the first second to the last.","🚀 It often shows up at the start of a rise.","🧠 Remember: green with no wicks = buyers have full control."],"p:marubozuBear":["🟥 A long red candle with no wicks at all.","🦹 Sellers were in charge from the first second to the last.","📉 It often shows up at the start of a fall.","🧠 Remember: red with no wicks = sellers have full control."],"p:hammer":["🔨 The candle looks like a hammer: a small body at the top and a long handle downward.","⬇️ The price fell a long way during the period.","⬆️ But buyers said no and pushed it back up.","📍 It's most interesting after a fall, at a floor.","🧠 Remember: the hammer hits the bottom, maybe the price turns up."],"p:invHammer":["🔨 An upside-down hammer: a small body at the bottom and a long wick upward.","⬆️ After a fall, buyers tried to push the price up.","🤔 They didn't quite manage yet, so you wait for a strong green candle afterwards.","🧠 Remember: inverted hammer = buyers are testing, wait for confirmation."],"p:hangingMan":["🧍 It looks exactly like the hammer, but shows up after a rise.","⬇️ During the period, sellers managed to push the price down a bit.","⚠️ It can be the first sign that the rise is getting tired.","🧠 Remember: same shape as the hammer, but at the top = warning."],"p:shootingStar":["🌠 A shooting star: a small body at the bottom and a long wick upward, after a rise.","⬆️ The price flew up high during the period.","⬇️ But sellers pushed it back down, like a falling star.","🧠 Remember: shooting star at the top = the price may fall."],"p:bullEng":["🐟 Two candles: first a small red one, then a big green one.","🍽️ The green one is so big it swallows the whole red one, like a big fish eating a small one.","💪 Buyers took over from the sellers.","🧠 Remember: big green eats small red after a fall = possible turn up."],"p:bearEng":["🐟 Two candles: first a small green one, then a big red one.","🍽️ The red one swallows the whole green one.","👎 Sellers took over from the buyers.","🧠 Remember: big red eats small green after a rise = possible turn down."],"p:piercing":["🔴 First a red candle.","🟢 Then a green one that starts lower but climbs up past the middle of the red one.","🗡️ It pierces through, hence the name.","🧠 Remember: green reaching over half the red = buyers are coming back."],"p:darkCloud":["🟢 First a green candle.","☁️ Then a red one that starts higher but falls below the middle of the green one, like a dark cloud.","⚠️ Sellers are starting to take over after a rise.","🧠 Remember: red falling below half the green = clouds are coming."],"p:bullHarami":["🤰 Harami means pregnant in Japanese.","🔴 A big red candle, then a small green one that fits inside it, like a baby in a belly.","🐢 Sellers have started to lose strength.","🧠 Remember: small green inside big red = weak signal, wait for confirmation."],"p:bearHarami":["🤰 A big green candle, then a small red one that fits inside it.","🐢 Buyers have started to lose strength.","⚠️ The signal is weak, so you wait for the next candle.","🧠 Remember: small red inside big green = warning, wait for confirmation."],"p:tweezBot":["🥢 Two candles with exactly the same lowest price, like the two tips of tweezers.","🛡️ Buyers defended the same floor twice.","🧠 Remember: two bottoms at the same level = a strong floor."],"p:tweezTop":["🥢 Two candles with exactly the same highest price.","🛡️ Sellers defended the same ceiling twice.","🧠 Remember: two tops at the same level = a strong ceiling."],"p:morningStar":["🌅 Three candles, like the sun coming up.","🔴 First a big red one: it's dark and the price is falling.","⭐ Then a small candle lower down: it goes quiet and still.","🟢 Last a big green one that climbs high: the sun rises!","🧠 Remember: morning star = night is over, the price may turn up."],"p:eveningStar":["🌇 Three candles, like the sun going down.","🟢 First a big green one: it's daytime and the price is rising.","⭐ Then a small candle higher up: it goes still.","🔴 Last a big red one that falls deep: the sun sets.","🧠 Remember: evening star = evening is coming, the price may turn down."],"p:soldiers":["💂💂💂 Three big green candles in a row, like soldiers marching upward.","⬆️ Each candle ends near its highest point.","💪 Buyers are strong.","⚠️ If the price has already risen for a very long time, they may be tired.","🧠 Remember: three green soldiers = a strong rise."],"p:crows":["🐦‍⬛🐦‍⬛🐦‍⬛ Three big red candles in a row, like crows flying downward.","⬇️ Each candle ends near its lowest point.","👎 Sellers are strong.","🧠 Remember: three black crows = a strong fall."],"p:insideUp":["1️⃣ A big red candle.","2️⃣ A small green one inside it, that's a harami.","3️⃣ A third green candle that closes higher than where the first one started. That's confirmation!","🧠 Remember: harami + confirmation = three inside up."],"p:insideDown":["1️⃣ A big green candle.","2️⃣ A small red one inside it, a harami.","3️⃣ A third red one that closes lower than where the first one started. Confirmed!","🧠 Remember: harami + confirmation down = three inside down."],"p:risingThree":["🟢 First a big green candle.","😮‍💨 Then three small red ones that stay inside it. The price takes a break, like a runner catching their breath.","🚀 Last a new big green one that reaches a new high.","🧠 Remember: a pause in the rise, then it continues."],"p:fallingThree":["🔴 First a big red candle.","😮‍💨 Then three small green ones inside it. A short pause.","📉 Last a new big red one that reaches a new low.","🧠 Remember: a pause in the fall, then it continues."]},"fr":{"c:Aktie":["🍕 Imagine qu'une entreprise est une grande pizza.","✂️ L'entreprise coupe la pizza en plein de toutes petites parts. Chaque part s'appelle une action.","🙋 Si tu achètes une action, tu possèdes un petit morceau de l'entreprise. Tu deviens actionnaire !","📈 Si l'entreprise va bien, les parts valent plus. Parfois, l'entreprise distribue aussi une partie de ses bénéfices : c'est le dividende.","🧠 À retenir : une action = un petit morceau d'une entreprise."],"c:Börsen":["🏪 La Bourse, c'est comme un immense marché, mais on y achète et vend des actions au lieu de fruits.","🙋‍♀️🙋 Il y a des gens qui veulent acheter et des gens qui veulent vendre.","🍦 Si beaucoup d'enfants veulent la même glace et qu'il y en a peu, le prix monte. Si peu la veulent, le prix baisse.","📈 C'est pareil pour les actions : plus de gens veulent acheter que vendre, et le prix monte.","🧠 À retenir : beaucoup d'acheteurs = prix en hausse, beaucoup de vendeurs = prix en baisse."],"c:Trading eller investering":["🌳 Un investisseur, c'est comme quelqu'un qui plante un arbre et attend des années qu'il pousse.","🏃 Un trader ressemble plutôt à un sprinteur. Il achète et vend vite, parfois le même jour.","⏱️ Le trader essaie de gagner de l'argent sur de petits mouvements de prix en peu de temps.","⚠️ Rapide ne veut pas dire facile. La plupart des gens qui tradent souvent perdent de l'argent.","🧠 À retenir : investisseur = longtemps, trader = peu de temps."],"c:Bid och ask":["🛒 Imagine que tu veux vendre ton vélo.","🙋 Un acheteur dit : je paie au maximum 99. C'est le bid, l'offre de l'acheteur.","🙋‍♀️ Un vendeur dit : je vends au minimum 100. C'est l'ask, le prix du vendeur.","↔️ L'écart entre 99 et 100 s'appelle le spread. C'est un peu comme des frais que tu paies quand tu achètes ou vends.","🧠 À retenir : bid = prix de l'acheteur, ask = prix du vendeur, spread = l'écart."],"c:Marknadsorder":["⚡ Un ordre au marché veut dire : achète maintenant, tout de suite, quel que soit le prix du moment.","🍬 Comme aller au rayon bonbons et dire : je le prends, peu importe le prix !","😬 C'est rapide, mais s'il y a peu de vendeurs, tu peux payer plus cher que prévu.","🧠 À retenir : ordre au marché = rapide, mais le prix n'est pas sûr."],"c:Limitorder":["🎯 Un ordre à cours limité veut dire : j'achète seulement si le prix est au maximum de tant.","🍭 Comme dire : j'achète la sucette si elle coûte 10 ou moins, sinon j'attends.","✅ Tu ne paies jamais plus que ton prix.","⏳ Mais si le prix ne descend jamais jusqu'à ton prix, il n'y a pas d'achat du tout.","🧠 À retenir : ordre limité = prix sûr, mais peut-être pas d'achat."],"c:Fyra priser per ljus":["🕯️ Une bougie sur le graphique raconte ce qui est arrivé au prix pendant une période, par exemple une journée.","1️⃣ Ouverture : le prix au début de la journée.","2️⃣ Plus haut : le prix le plus haut de la journée. 3️⃣ Plus bas : le prix le plus bas.","4️⃣ Clôture : le prix à la fin de la journée.","🧠 À retenir : une bougie = quatre prix : ouverture, plus haut, plus bas, clôture."],"c:Grönt och rött":["🕯️ Regarde la partie épaisse de la bougie. On l'appelle le corps.","🟢 Bougie verte : le prix a fini plus haut qu'au début. Il a monté.","🔴 Bougie rouge : le prix a fini plus bas qu'au début. Il a baissé.","🧠 À retenir : vert = hausse, rouge = baisse, par rapport au début de la période."],"c:Veken":["🕯️ Les petits traits au-dessus et au-dessous du corps s'appellent des mèches, comme la mèche d'une vraie bougie.","⬆️ Le haut de la mèche du dessus, c'est le prix le plus haut.","⬇️ Le bas de la mèche du dessous, c'est le prix le plus bas.","🎈 La mèche montre jusqu'où le prix s'est envolé avant de revenir.","🧠 À retenir : mèches = prix le plus haut et le plus bas."],"c:Tidsram":["⏰ Une bougie peut montrer une minute, une heure, un jour ou une semaine. C'est l'unité de temps.","🔍 C'est comme zoomer et dézoomer sur une carte.","🌦️ Une journée peut avoir une heure de pluie et rester ensoleillée. Le prix peut aussi baisser une heure mais monter sur la semaine.","🧠 À retenir : vérifie toujours quelle unité de temps tu regardes."],"c:Volym":["📊 Le volume, c'est le nombre d'actions achetées et vendues. On le voit en barres sous le graphique.","🎉 Un gros volume, c'est comme une fête pleine de monde : beaucoup de gens participent.","🤫 Un petit volume, c'est comme une salle presque vide : seulement quelques personnes.","💪 Quand le prix bouge et que beaucoup de gens participent, ça compte généralement plus.","🧠 À retenir : gros volume = beaucoup de participants, le mouvement compte plus."],"c:Upptrend":["🪜 Une tendance haussière, c'est comme un escalier qui monte.","⛰️ Le prix fait des sommets et des creux, comme de petites collines et vallées.","⬆️ Dans une tendance haussière, chaque sommet est plus haut que le précédent, et chaque creux aussi.","🧠 À retenir : sommets plus hauts et creux plus hauts = tendance haussière."],"c:Nedtrend":["🛝 Une tendance baissière, c'est comme un escalier ou un toboggan qui descend.","⬇️ Chaque sommet est plus bas que le précédent.","⬇️ Chaque creux est aussi plus bas que le précédent.","🧠 À retenir : sommets plus bas et creux plus bas = tendance baissière."],"c:Sidled":["🏓 Parfois, le prix ne monte ni ne descend. Il rebondit d'avant en arrière comme une balle de ping-pong.","📏 Il rebondit entre un plancher et un plafond qui restent à peu près au même endroit.","😴 On appelle ça un marché sans tendance ou un range. Personne ne gagne.","🧠 À retenir : mêmes sommets et mêmes creux = sans tendance."],"c:Stöd":["🏀 Imagine une balle qui rebondit sur le sol.","⬇️ Le prix baisse, mais à un certain niveau il arrête de baisser et remonte.","🛒 C'est parce que beaucoup d'acheteurs trouvent le prix bon marché à cet endroit et achètent.","🟢 Ce niveau s'appelle un support. C'est comme un plancher.","🧠 À retenir : support = plancher où les acheteurs arrivent."],"c:Motstånd":["🏠 Imagine que tu lances une balle dans une pièce. Elle touche le plafond et retombe.","⬆️ Le prix monte, mais à un certain niveau il redescend plusieurs fois.","💰 Là, beaucoup de gens trouvent le prix cher et vendent.","🔴 Ce niveau s'appelle une résistance. C'est comme un plafond.","🧠 À retenir : résistance = plafond où les vendeurs prennent le dessus."],"c:Utbrott":["🚀 Parfois, le prix traverse le plafond. C'est une cassure.","🏢 C'est comme monter d'un étage dans un immeuble.","🔄 L'ancien plafond devient le plancher du nouvel étage. Une ancienne résistance peut devenir un nouveau support.","⚠️ Mais parfois la cassure est fausse et le prix retombe.","🧠 À retenir : à travers le plafond, et le plafond peut devenir plancher."],"c:Kroppens storlek":["🕯️ Regarde la longueur du corps épais.","🦸 Corps long : un camp était beaucoup plus fort. Les acheteurs s'il est vert, les vendeurs s'il est rouge.","🤝 Corps court : acheteurs et vendeurs étaient à peu près aussi forts. Comme un tir à la corde où la corde bouge à peine.","🧠 À retenir : corps long = camp fort, corps court = combat égal."],"c:Vekar betyder avvisning":["🎾 Une longue mèche, c'est comme une balle qui rebondit sur un mur et revient.","⬇️ Longue mèche en bas : le prix est descendu loin, mais les acheteurs ont dit non et l'ont fait remonter.","⬆️ Longue mèche en haut : le prix est monté loin, mais les vendeurs ont dit non et l'ont fait redescendre.","🧠 À retenir : longue mèche = le prix est allé là-bas mais a été renvoyé."],"c:Marubozu":["🕯️ Un marubozu est une bougie sans aucune mèche. Juste un corps épais.","🟢 Marubozu vert : les acheteurs ont décidé tout le temps, de la première seconde à la dernière.","🔴 Marubozu rouge : les vendeurs ont décidé tout le temps.","🧠 À retenir : pas de mèches = un camp avait tout le contrôle."],"c:Kontext":["☂️ Un parapluie ne veut pas dire la même chose quand il pleut et quand il fait soleil.","🔨 La même forme de bougie peut aussi vouloir dire des choses différentes selon ce qui s'est passé avant.","⬇️ Après une baisse, la forme s'appelle un marteau et peut signifier que le prix veut remonter.","⬆️ Après une hausse, la même forme s'appelle un pendu et c'est un avertissement.","🧠 À retenir : regarde toujours ce qui s'est passé avant la figure."],"c:Plats":["📍 L'endroit où apparaît une figure est important.","🏀 Une figure sur un plancher (support) ou un plafond (résistance), c'est comme une balle contre un mur : il se passe quelque chose.","🌫️ Une figure au milieu de nulle part compte généralement moins.","🧠 À retenir : les figures aux niveaux importants sont plus intéressantes."],"c:Bekräftelse":["⏳ Une figure est comme un indice, pas une réponse sûre.","👀 C'est pour ça que beaucoup attendent la bougie suivante avant d'agir.","✅ Si la bougie suivante clôture au-dessus du plus haut de la figure, la figure haussière est soutenue. C'est la confirmation.","🧠 À retenir : attends la bougie suivante avant de faire confiance à la figure."],"c:Ingång":["🚪 L'entrée, c'est le moment où tu achètes et entres dans le trade.","⬆️ Après une figure haussière, beaucoup attendent que le prix passe au-dessus du plus haut de la figure.","✅ Le prix a alors montré qu'il veut vraiment monter.","🧠 À retenir : entre quand le prix casse au-dessus du sommet de la figure."],"c:Stop-loss":["🛑 Un stop-loss est un frein d'urgence. Tu décides à l'avance où tu vends si le prix baisse.","📉 Si le prix arrive là, les actions sont vendues automatiquement, pour que la perte ne grossisse pas.","🦘 Attention : si le prix saute par-dessus le niveau, par exemple pendant la nuit, tu peux vendre un peu plus bas que prévu.","📍 Après une figure, on place souvent le frein juste sous le plus bas de la figure. Si le prix y arrive, la figure n'a pas marché.","🧠 À retenir : pas de trade sans frein d'urgence."],"c:Mål":["🎯 L'objectif, c'est là où tu prévois de vendre avec un gain.","⛰️ On place souvent l'objectif au prochain plafond, la prochaine résistance.","⚖️ Ensuite on compare : quelle distance jusqu'à l'objectif, et jusqu'au frein d'urgence ?","🧠 À retenir : l'objectif doit être plus loin que le stop."],"c:Falska signaler":["🎣 Toutes les figures ne marchent pas. Parfois le poisson ne mord pas, même si tu fais tout bien.","❌ Une figure peut sembler parfaite et quand même échouer.","🛑 C'est pour ça que les petites pertes et le frein d'urgence comptent plus que la figure parfaite.","🧠 À retenir : perds peu quand tu te trompes, et tu dureras longtemps."],"c:Medelvärde":["🧮 Une moyenne, c'est la valeur du milieu. Additionne les prix et divise par leur nombre.","🌡️ Comme calculer la température moyenne d'une semaine au lieu de regarder chaque jour.","〰️ La ligne devient douce et calme et montre dans quelle direction va le prix.","🔁 On dit mobile parce qu'elle est recalculée chaque jour avec les derniers jours.","🧠 À retenir : moyenne mobile = ligne calme qui montre la tendance."],"c:Pris och MA":["📈 Si le prix est au-dessus d'une ligne de moyenne qui monte, c'est plutôt positif.","📉 Si le prix est sous une ligne qui descend, c'est plutôt négatif.","🤔 C'est un indice, pas une promesse.","🧠 À retenir : au-dessus d'une ligne qui monte = bon signe, sous une ligne qui baisse = mauvais signe."],"c:RSI":["🏃 Le RSI est comme un compteur de vitesse pour le prix. Il montre à quelle vitesse et avec quelle force le prix a bougé.","🔢 Il va de 0 à 100.","🔥 Au-dessus de 70, on dit suracheté : le prix a couru très vite vers le haut.","🧊 En dessous de 30, on dit survendu : le prix est tombé très vite.","🧠 À retenir : RSI au-dessus de 70 = monté très vite, sous 30 = baissé très vite."],"c:Varning":["🏃‍♂️ Un coureur qui va vite n'est pas obligé de s'arrêter tout de suite.","🔥 Suracheté ne veut pas dire que le prix doit baisser maintenant.","💪 Dans les tendances fortes, le RSI peut rester haut longtemps.","🧠 À retenir : RSI haut = sois prudent, pas une vente automatique."],"c:1–2-procentsregeln":["🍬 Imagine que tu as 100 bonbons.","🎲 Si tu ne mises que 1 ou 2 bonbons à chaque fois, il t'en reste plein même si tu perds plusieurs fois de suite.","💥 Si tu mises 50 bonbons, deux pertes suffisent pour que presque tout disparaisse.","🧠 À retenir : risque au maximum 1 à 2 % du compte par trade."],"c:Förluster är asymmetriska":["🍰 Tu as un gâteau. Si la moitié disparaît, il te reste un demi-gâteau.","➕ Pour retrouver un gâteau entier, le demi-gâteau doit doubler. C'est 100 % de plus !","📉 Perdre 50 % est donc beaucoup plus facile que de le regagner ensuite.","🧠 À retenir : protège ton argent d'abord, car les grosses pertes sont dures à rattraper."],"c:Positionsstorlek":["❓ La taille de position veut dire : combien d'actions dois-je acheter ?","💰 D'abord, tu décides combien tu acceptes de perdre, par exemple 100.","📏 Ensuite, tu regardes la distance jusqu'au frein d'urgence, par exemple 2 par action.","➗ 100 divisé par 2 = 50 actions. Si le frein se déclenche, tu ne perds que 100.","🧠 À retenir : nombre d'actions = risque en argent ÷ distance au stop-loss."],"c:Risk/reward":["⚖️ Le risque/rendement est une balance. D'un côté : ce que tu peux perdre. De l'autre : ce que tu peux gagner.","🍬 Risquer 1 bonbon pour pouvoir en gagner 3. On écrit 1:3.","✅ Alors avoir raison environ 1 fois sur 4 suffit pour être à l'équilibre, sans compter les frais.","🧠 À retenir : le gain possible doit être plus grand que la perte possible."],"c:FOMO":["😱 Le FOMO, c'est la peur de rater quelque chose.","🎢 Tout le monde parle d'une action qui s'est envolée, et tu veux sauter dedans toi aussi.","🏔️ Mais souvent on achète alors que le prix est déjà au sommet.","🧘 Mieux vaut suivre son plan. Il y a toujours d'autres occasions.","🧠 À retenir : ne cours pas après, un autre bus arrivera."],"c:Hämndtrading":["😤 Le trading de revanche, c'est quand on a perdu, qu'on s'énerve et qu'on veut tout regagner tout de suite.","🎰 On prend alors plus de risques que d'habitude, comme tout miser d'un coup.","📉 Ça finit souvent par une perte encore plus grande.","🧠 À retenir : après une perte, fais une pause."],"c:Tradingplan":["🗺️ Un plan de trading, c'est comme une carte avant un voyage.","📝 Tu écris à l'avance : ce que tu achètes, quand, où est le frein d'urgence et combien tu risques.","🧊 Comme ça, tu décides la tête froide au lieu de décider stressé.","🧠 À retenir : planifie d'abord, trade ensuite."],"c:Avgifter":["🧾 Chaque fois que tu achètes ou vends, ça coûte un peu d'argent. Ce sont les frais de courtage.","↔️ Le spread, l'écart entre prix d'achat et de vente, coûte aussi.","🔁 Si tu trades souvent, tous ces petits frais font une grosse somme.","🧠 À retenir : plus de trades = plus de frais."],"c:ISK":["🏦 L'ISK est une sorte de compte d'épargne pour actions et fonds en Suède.","🧾 Tu ne paies pas d'impôt à chaque gain. À la place, tu paies un petit impôt chaque année, calculé sur ce qu'il y a sur le compte.","🎁 Depuis 2026, les 300 000 premières couronnes sont exonérées, au total par personne. Les règles peuvent changer, vérifie auprès de l'administration fiscale suédoise.","🧠 À retenir : ISK = petit impôt annuel au lieu d'un impôt sur chaque gain."],"c:Varningstecken":["🚨 Quelqu'un te promet que tu vas forcément devenir riche vite ? C'est presque toujours une arnaque.","⏰ Quelqu'un te dit de te dépêcher maintenant ? C'est une astuce pour que tu n'aies pas le temps de réfléchir.","💬 Les groupes dans des applis qui veulent que tu leur envoies de l'argent sont une arnaque courante.","🔍 Vérifie toujours l'entreprise auprès de l'autorité financière.","🧠 À retenir : garanti + pressé = va-t'en."],"p:doji":["🕯️ Regarde la bougie : le corps est presque juste un trait.","🤝 Le prix a fini presque exactement là où il a commencé. Acheteurs et vendeurs ont tiré la corde aussi fort.","⏸️ Après un long mouvement, ça peut vouloir dire que la force s'épuise.","🧠 À retenir : doji = match nul, attends la bougie suivante."],"p:dragonfly":["🪰 La bougie ressemble à un T, comme une libellule.","⬇️ Les vendeurs ont poussé le prix très bas.","⬆️ Mais les acheteurs l'ont fait remonter tout en haut avant la fin de la période.","🧠 À retenir : une libellule après une baisse peut signifier que les acheteurs se réveillent."],"p:gravestone":["🪦 La bougie ressemble à un T à l'envers, comme une pierre tombale.","⬆️ Les acheteurs ont poussé le prix très haut.","⬇️ Mais les vendeurs l'ont fait redescendre jusqu'en bas.","🧠 À retenir : une pierre tombale après une hausse annonce une baisse possible."],"p:longDoji":["🕯️ Regarde : presque pas de corps, mais de très longues mèches des deux côtés.","🎢 Le prix est allé très haut et très bas, mais a fini là où il a commencé.","🤷 Personne ne sait qui va gagner. Beaucoup d'incertitude.","🧠 À retenir : longues jambes = grande confusion, attends de voir."],"p:spinning":["🌀 Une toupie a un petit corps au milieu et des mèches des deux côtés.","🤝 Aucun camp n'a pris le contrôle pendant cette période.","⏸️ Elle apparaît souvent quand la tendance fait une pause.","🧠 À retenir : toupie = pause, attends la bougie suivante."],"p:marubozuBull":["🟩 Une longue bougie verte sans aucune mèche.","🦸 Les acheteurs ont décidé de la première à la dernière seconde.","🚀 On la voit souvent au début d'une hausse.","🧠 À retenir : verte sans mèches = les acheteurs contrôlent tout."],"p:marubozuBear":["🟥 Une longue bougie rouge sans aucune mèche.","🦹 Les vendeurs ont décidé de la première à la dernière seconde.","📉 On la voit souvent au début d'une baisse.","🧠 À retenir : rouge sans mèches = les vendeurs contrôlent tout."],"p:hammer":["🔨 La bougie ressemble à un marteau : un petit corps en haut et un long manche vers le bas.","⬇️ Le prix est descendu très bas pendant la période.","⬆️ Mais les acheteurs ont dit non et l'ont fait remonter.","📍 Il est surtout intéressant après une baisse, sur un plancher.","🧠 À retenir : le marteau tape le fond, le prix va peut-être remonter."],"p:invHammer":["🔨 Un marteau à l'envers : un petit corps en bas et une longue mèche vers le haut.","⬆️ Après une baisse, les acheteurs ont essayé de faire monter le prix.","🤔 Ils n'y sont pas encore arrivés, alors on attend une forte bougie verte ensuite.","🧠 À retenir : marteau inversé = les acheteurs testent, attends la confirmation."],"p:hangingMan":["🧍 Il ressemble exactement au marteau, mais apparaît après une hausse.","⬇️ Pendant la période, les vendeurs ont réussi à faire baisser un peu le prix.","⚠️ Ça peut être le premier signe que la hausse fatigue.","🧠 À retenir : même forme que le marteau, mais au sommet = avertissement."],"p:shootingStar":["🌠 Une étoile filante : un petit corps en bas et une longue mèche vers le haut, après une hausse.","⬆️ Le prix s'est envolé très haut pendant la période.","⬇️ Mais les vendeurs l'ont fait redescendre, comme une étoile qui tombe.","🧠 À retenir : étoile filante au sommet = le prix peut baisser."],"p:bullEng":["🐟 Deux bougies : d'abord une petite rouge, puis une grande verte.","🍽️ La verte est si grande qu'elle avale toute la rouge, comme un gros poisson qui mange un petit.","💪 Les acheteurs ont pris le relais des vendeurs.","🧠 À retenir : grande verte avale petite rouge après une baisse = retournement possible vers le haut."],"p:bearEng":["🐟 Deux bougies : d'abord une petite verte, puis une grande rouge.","🍽️ La rouge avale toute la verte.","👎 Les vendeurs ont pris le relais des acheteurs.","🧠 À retenir : grande rouge avale petite verte après une hausse = retournement possible vers le bas."],"p:piercing":["🔴 D'abord une bougie rouge.","🟢 Puis une verte qui commence plus bas mais remonte au-delà du milieu de la rouge.","🗡️ Elle la transperce, d'où son nom.","🧠 À retenir : une verte qui dépasse la moitié de la rouge = les acheteurs reviennent."],"p:darkCloud":["🟢 D'abord une bougie verte.","☁️ Puis une rouge qui commence plus haut mais tombe sous le milieu de la verte, comme un nuage noir.","⚠️ Les vendeurs commencent à prendre le dessus après une hausse.","🧠 À retenir : une rouge qui tombe sous la moitié de la verte = les nuages arrivent."],"p:bullHarami":["🤰 Harami veut dire enceinte en japonais.","🔴 Une grande bougie rouge, puis une petite verte qui tient dedans, comme un bébé dans un ventre.","🐢 Les vendeurs commencent à perdre de la force.","🧠 À retenir : petite verte dans grande rouge = signal faible, attends la confirmation."],"p:bearHarami":["🤰 Une grande bougie verte, puis une petite rouge qui tient dedans.","🐢 Les acheteurs commencent à perdre de la force.","⚠️ Le signal est faible, alors on attend la bougie suivante.","🧠 À retenir : petite rouge dans grande verte = avertissement, attends la confirmation."],"p:tweezBot":["🥢 Deux bougies avec exactement le même plus bas, comme les deux pointes d'une pince à épiler.","🛡️ Les acheteurs ont défendu le même plancher deux fois.","🧠 À retenir : deux creux au même niveau = plancher solide."],"p:tweezTop":["🥢 Deux bougies avec exactement le même plus haut.","🛡️ Les vendeurs ont défendu le même plafond deux fois.","🧠 À retenir : deux sommets au même niveau = plafond solide."],"p:morningStar":["🌅 Trois bougies, comme le soleil qui se lève.","🔴 D'abord une grande rouge : il fait sombre et le prix baisse.","⭐ Puis une petite bougie plus bas : tout devient calme.","🟢 Enfin une grande verte qui monte haut : le soleil se lève !","🧠 À retenir : étoile du matin = la nuit est finie, le prix peut remonter."],"p:eveningStar":["🌇 Trois bougies, comme le soleil qui se couche.","🟢 D'abord une grande verte : il fait jour et le prix monte.","⭐ Puis une petite bougie plus haut : tout devient calme.","🔴 Enfin une grande rouge qui tombe bas : le soleil se couche.","🧠 À retenir : étoile du soir = le soir arrive, le prix peut baisser."],"p:soldiers":["💂💂💂 Trois grandes bougies vertes d'affilée, comme des soldats qui marchent vers le haut.","⬆️ Chaque bougie finit près de son plus haut.","💪 Les acheteurs sont forts.","⚠️ Si le prix monte déjà depuis très longtemps, ils sont peut-être fatigués.","🧠 À retenir : trois soldats verts = forte hausse."],"p:crows":["🐦‍⬛🐦‍⬛🐦‍⬛ Trois grandes bougies rouges d'affilée, comme des corbeaux qui volent vers le bas.","⬇️ Chaque bougie finit près de son plus bas.","👎 Les vendeurs sont forts.","🧠 À retenir : trois corbeaux noirs = forte baisse."],"p:insideUp":["1️⃣ Une grande bougie rouge.","2️⃣ Une petite verte dedans : c'est un harami.","3️⃣ Une troisième bougie verte qui clôture plus haut que l'ouverture de la première. C'est la confirmation !","🧠 À retenir : harami + confirmation = trois à l'intérieur haussier."],"p:insideDown":["1️⃣ Une grande bougie verte.","2️⃣ Une petite rouge dedans : un harami.","3️⃣ Une troisième rouge qui clôture plus bas que l'ouverture de la première. Confirmé !","🧠 À retenir : harami + confirmation vers le bas = trois à l'intérieur baissier."],"p:risingThree":["🟢 D'abord une grande bougie verte.","😮‍💨 Puis trois petites rouges qui restent dedans. Le prix fait une pause, comme un coureur qui reprend son souffle.","🚀 Enfin une nouvelle grande verte qui atteint un nouveau sommet.","🧠 À retenir : pause dans la hausse, puis elle continue."],"p:fallingThree":["🔴 D'abord une grande bougie rouge.","😮‍💨 Puis trois petites vertes dedans. Une courte pause.","📉 Enfin une nouvelle grande rouge qui atteint un nouveau creux.","🧠 À retenir : pause dans la baisse, puis elle continue."]},"ar":{"c:Aktie":["🍕 تخيّل أن الشركة بيتزا كبيرة.","✂️ تقطّع الشركة البيتزا إلى قطع صغيرة كثيرة جدًا. كل قطعة اسمها سهم.","🙋 إذا اشتريت سهمًا، فأنت تملك قطعة صغيرة من الشركة. تصبح شريكًا!","📈 إذا نجحت الشركة، تصبح القطع أغلى. وأحيانًا توزّع الشركة جزءًا من أرباحها، ويسمى ذلك توزيعات الأرباح.","🧠 تذكّر: السهم = قطعة صغيرة من شركة."],"c:Börsen":["🏪 البورصة مثل سوق ضخم، لكن الناس يبيعون ويشترون فيه الأسهم بدل الفواكه.","🙋‍♀️🙋 فيه أناس يريدون الشراء وأناس يريدون البيع.","🍦 إذا أراد أطفال كثيرون نفس المثلجات وكانت قليلة، يرتفع السعر. وإذا أرادها قليلون، ينخفض السعر.","📈 الأسهم كذلك: إذا كان الراغبون في الشراء أكثر من الراغبين في البيع، يرتفع السعر.","🧠 تذكّر: مشترون كثيرون = السعر يرتفع، بائعون كثيرون = السعر ينخفض."],"c:Trading eller investering":["🌳 المستثمر مثل شخص يزرع شجرة وينتظر سنوات طويلة حتى تكبر.","🏃 أما المتداول فهو أشبه بالعدّاء. يشتري ويبيع بسرعة، أحيانًا في اليوم نفسه.","⏱️ يحاول المتداول أن يربح من تحركات صغيرة في السعر خلال وقت قصير.","⚠️ السرعة لا تعني السهولة. معظم من يتداولون كثيرًا يخسرون المال.","🧠 تذكّر: المستثمر = وقت طويل، المتداول = وقت قصير."],"c:Bid och ask":["🛒 تخيّل أنك تريد بيع دراجتك.","🙋 يقول مشترٍ: سأدفع 99 على الأكثر. هذا اسمه سعر الطلب (bid)، أي عرض المشتري.","🙋‍♀️ ويقول بائع: سأبيع بـ 100 على الأقل. هذا اسمه سعر العرض (ask)، أي سعر البائع.","↔️ الفرق بين 99 و100 اسمه الفارق (spread). إنه يشبه رسمًا صغيرًا تدفعه عندما تتداول.","🧠 تذكّر: bid = سعر المشتري، ask = سعر البائع، spread = الفرق بينهما."],"c:Marknadsorder":["⚡ أمر السوق يعني: اشترِ الآن، فورًا، مهما كان السعر في هذه اللحظة.","🍬 مثل أن تذهب إلى رف الحلوى وتقول: سآخذها، مهما كان سعرها!","😬 إنه سريع، لكن إذا كان البائعون قليلين فقد تدفع أكثر مما توقعت.","🧠 تذكّر: أمر السوق = سريع، لكن السعر غير مضمون."],"c:Limitorder":["🎯 الأمر المحدد يعني: لن أشتري إلا إذا كان السعر بهذا المقدار أو أقل.","🍭 مثل أن تقول: سأشتري المصاصة إذا كان سعرها 10 أو أقل، وإلا سأنتظر.","✅ لن تدفع أبدًا أكثر من سعرك.","⏳ لكن إذا لم ينزل السعر أبدًا إلى سعرك، فلن تتم الصفقة.","🧠 تذكّر: الأمر المحدد = سعر مضمون، لكن ربما لا يتم الشراء."],"c:Fyra priser per ljus":["🕯️ الشمعة في الرسم البياني تحكي ما حدث للسعر خلال فترة، مثل يوم واحد.","1️⃣ الافتتاح: السعر عندما بدأ اليوم.","2️⃣ الأعلى: أعلى سعر في اليوم. 3️⃣ الأدنى: أقل سعر.","4️⃣ الإغلاق: السعر عندما انتهى اليوم.","🧠 تذكّر: الشمعة الواحدة = أربعة أسعار: الافتتاح والأعلى والأدنى والإغلاق."],"c:Grönt och rött":["🕯️ انظر إلى الجزء السميك من الشمعة. اسمه الجسم.","🟢 الشمعة الخضراء: انتهى السعر أعلى مما بدأ. أي أنه ارتفع.","🔴 الشمعة الحمراء: انتهى السعر أقل مما بدأ. أي أنه انخفض.","🧠 تذكّر: الأخضر = صعود، الأحمر = هبوط، مقارنة ببداية الفترة."],"c:Veken":["🕯️ الخطوط الرفيعة فوق الجسم وتحته اسمها الفتائل، مثل فتيل الشمعة الحقيقية.","⬆️ رأس الفتيل العلوي هو أعلى سعر.","⬇️ أسفل الفتيل السفلي هو أدنى سعر.","🎈 يُظهر الفتيل إلى أي مدى طار السعر قبل أن يعود.","🧠 تذكّر: الفتائل = أعلى سعر وأدنى سعر."],"c:Tidsram":["⏰ يمكن أن تمثّل الشمعة دقيقة أو ساعة أو يومًا أو أسبوعًا. هذا اسمه الإطار الزمني.","🔍 الأمر مثل التكبير والتصغير على الخريطة.","🌦️ قد تمطر ساعة في يوم مشمس عمومًا. وقد ينخفض السعر ساعة ويرتفع خلال الأسبوع.","🧠 تذكّر: تأكد دائمًا من الإطار الزمني الذي تنظر إليه."],"c:Volym":["📊 حجم التداول هو عدد الأسهم التي بيعت واشتُريت. يظهر كأعمدة تحت الرسم.","🎉 الحجم الكبير مثل حفلة مزدحمة: كثيرون يشاركون.","🤫 الحجم الصغير مثل غرفة شبه فارغة: قلة فقط هناك.","💪 عندما يتحرك السعر ويشارك كثيرون، يكون لذلك عادة وزن أكبر.","🧠 تذكّر: حجم كبير = مشاركون كثيرون والحركة أهم."],"c:Upptrend":["🪜 الاتجاه الصاعد مثل درج يصعد إلى الأعلى.","⛰️ يصنع السعر قممًا وقيعانًا، مثل تلال ووديان صغيرة.","⬆️ في الاتجاه الصاعد، كل قمة أعلى من القمة السابقة، وكل قاع أعلى من القاع السابق.","🧠 تذكّر: قمم أعلى وقيعان أعلى = اتجاه صاعد."],"c:Nedtrend":["🛝 الاتجاه الهابط مثل درج أو زحليقة تنزل إلى الأسفل.","⬇️ كل قمة أدنى من القمة السابقة.","⬇️ وكل قاع أيضًا أدنى من القاع السابق.","🧠 تذكّر: قمم أدنى وقيعان أدنى = اتجاه هابط."],"c:Sidled":["🏓 أحيانًا لا يصعد السعر ولا ينزل. بل يرتد ذهابًا وإيابًا مثل كرة تنس الطاولة.","📏 يرتد بين أرضية وسقف يبقيان تقريبًا في المكان نفسه.","😴 هذا اسمه الاتجاه العرضي أو النطاق. لا أحد يفوز.","🧠 تذكّر: قمم متشابهة وقيعان متشابهة = اتجاه عرضي."],"c:Stöd":["🏀 تخيّل كرة ترتد على الأرض.","⬇️ ينخفض السعر، لكنه عند مستوى معيّن يتوقف عن الهبوط ويرتد إلى الأعلى.","🛒 السبب أن مشترين كثيرين يرون السعر رخيصًا هناك فيشترون.","🟢 هذا المستوى اسمه الدعم. إنه مثل الأرضية.","🧠 تذكّر: الدعم = أرضية يدخل عندها المشترون."],"c:Motstånd":["🏠 تخيّل أنك ترمي كرة إلى أعلى في غرفة. تصطدم بالسقف وتسقط.","⬆️ يرتفع السعر، لكنه عند مستوى معيّن يعود إلى الأسفل مرات عدة.","💰 هناك يرى كثيرون أن السعر غالٍ فيبيعون.","🔴 هذا المستوى اسمه المقاومة. إنه مثل السقف.","🧠 تذكّر: المقاومة = سقف يسيطر عنده البائعون."],"c:Utbrott":["🚀 أحيانًا يخترق السعر السقف. هذا اسمه الاختراق.","🏢 الأمر مثل الصعود طابقًا في مبنى.","🔄 يصبح السقف القديم أرضية الطابق الجديد. المقاومة القديمة قد تصبح دعمًا جديدًا.","⚠️ لكن أحيانًا يكون الاختراق كاذبًا ويعود السعر إلى الأسفل.","🧠 تذكّر: عبر السقف، والسقف قد يصبح أرضية."],"c:Kroppens storlek":["🕯️ انظر إلى طول الجسم السميك.","🦸 جسم طويل: أحد الطرفين كان أقوى بكثير. المشترون إذا كان أخضر، والبائعون إذا كان أحمر.","🤝 جسم قصير: المشترون والبائعون كانوا متقاربين في القوة. مثل لعبة شد الحبل حين لا يكاد الحبل يتحرك.","🧠 تذكّر: جسم طويل = طرف قوي، جسم قصير = معركة متكافئة."],"c:Vekar betyder avvisning":["🎾 الفتيل الطويل مثل كرة ترتد عن الحائط وتعود.","⬇️ فتيل سفلي طويل: نزل السعر كثيرًا، لكن المشترين قالوا لا ودفعوه إلى الأعلى.","⬆️ فتيل علوي طويل: صعد السعر كثيرًا، لكن البائعين قالوا لا ودفعوه إلى الأسفل.","🧠 تذكّر: فتيل طويل = وصل السعر إلى هناك لكنه رُدّ."],"c:Marubozu":["🕯️ الماروبوزو شمعة بلا أي فتائل. جسم سميك فقط.","🟢 ماروبوزو أخضر: المشترون سيطروا طوال الوقت، من أول ثانية إلى آخر ثانية.","🔴 ماروبوزو أحمر: البائعون سيطروا طوال الوقت.","🧠 تذكّر: بلا فتائل = طرف واحد كان مسيطرًا تمامًا."],"c:Kontext":["☂️ المظلة تعني شيئًا عندما تمطر وشيئًا آخر عندما تشرق الشمس.","🔨 وشكل الشمعة نفسه قد يعني أشياء مختلفة حسب ما حدث قبله.","⬇️ بعد هبوط، يسمى الشكل المطرقة وقد يعني أن السعر يريد الصعود.","⬆️ وبعد صعود، يسمى الشكل نفسه الرجل المشنوق وهو تحذير.","🧠 تذكّر: انظر دائمًا إلى ما حدث قبل النموذج."],"c:Plats":["📍 المكان الذي يظهر فيه النموذج مهم.","🏀 النموذج عند أرضية (دعم) أو سقف (مقاومة) مثل كرة تصطدم بحائط: هناك يحدث شيء ما.","🌫️ النموذج في منتصف اللامكان يعني عادة أقل.","🧠 تذكّر: النماذج عند المستويات المهمة أكثر أهمية."],"c:Bekräftelse":["⏳ النموذج مثل دليل صغير، وليس جوابًا أكيدًا.","👀 لهذا ينتظر كثيرون الشمعة التالية قبل أن يفعلوا شيئًا.","✅ إذا أغلقت الشمعة التالية فوق أعلى سعر في النموذج، يكون النموذج الصاعد قد تأكد. هذا اسمه التأكيد.","🧠 تذكّر: انتظر الشمعة التالية قبل أن تثق بالنموذج."],"c:Ingång":["🚪 الدخول يعني اللحظة التي تشتري فيها وتدخل الصفقة.","⬆️ بعد نموذج صاعد، ينتظر كثيرون حتى يتجاوز السعر أعلى سعر في النموذج.","✅ عندها يكون السعر قد أظهر أنه يريد الصعود فعلًا.","🧠 تذكّر: ادخل عندما يخترق السعر قمة النموذج."],"c:Stop-loss":["🛑 وقف الخسارة مثل فرامل الطوارئ. تقرر مسبقًا أين ستبيع إذا انخفض السعر.","📉 إذا وصل السعر إلى هناك، تُباع الأسهم تلقائيًا حتى لا تكبر الخسارة.","🦘 انتبه: إذا قفز السعر فوق المستوى، مثلًا أثناء الليل، فقد تبيع بسعر أقل قليلًا مما خططت.","📍 بعد النموذج، توضع الفرامل غالبًا تحت أدنى سعر في النموذج مباشرة. إذا وصل السعر إليها، فالنموذج لم ينجح.","🧠 تذكّر: لا صفقة بدون فرامل طوارئ."],"c:Mål":["🎯 الهدف هو المكان الذي تنوي البيع عنده بربح.","⛰️ غالبًا يُوضع الهدف عند السقف التالي، أي المقاومة التالية.","⚖️ ثم نقارن: كم المسافة إلى الهدف، وكم المسافة إلى الفرامل؟","🧠 تذكّر: يجب أن يكون الهدف أبعد من الوقف."],"c:Falska signaler":["🎣 ليست كل النماذج تنجح. أحيانًا لا تعلق السمكة رغم أنك فعلت كل شيء صحيحًا.","❌ قد يبدو النموذج مثاليًا ثم يفشل.","🛑 لهذا فالخسائر الصغيرة وفرامل الطوارئ أهم من العثور على النموذج المثالي.","🧠 تذكّر: اخسر قليلًا عندما تخطئ، وستصمد طويلًا."],"c:Medelvärde":["🧮 المتوسط هو القيمة الوسطى. اجمع الأسعار واقسمها على عددها.","🌡️ مثل حساب متوسط الحرارة لأسبوع بدل النظر إلى كل يوم.","〰️ يصبح الخط ناعمًا وهادئًا ويُظهر اتجاه السعر.","🔁 يسمى متحركًا لأنه يُعاد حسابه كل يوم باستخدام آخر الأيام.","🧠 تذكّر: المتوسط المتحرك = خط هادئ يُظهر الاتجاه."],"c:Pris och MA":["📈 إذا كان السعر فوق خط متوسط يتجه إلى الأعلى، فهذا يبدو إيجابيًا.","📉 إذا كان السعر تحت خط يتجه إلى الأسفل، فهذا يبدو سلبيًا.","🤔 إنه دليل، وليس وعدًا.","🧠 تذكّر: فوق خط صاعد = علامة جيدة، تحت خط هابط = علامة سيئة."],"c:RSI":["🏃 مؤشر RSI مثل عدّاد السرعة للسعر. يُظهر مدى سرعة وقوة حركة السعر.","🔢 يتراوح من 0 إلى 100.","🔥 فوق 70 يسمى تشبّعًا شرائيًا: ركض السعر إلى الأعلى بسرعة كبيرة.","🧊 تحت 30 يسمى تشبّعًا بيعيًا: سقط السعر بسرعة كبيرة.","🧠 تذكّر: RSI فوق 70 = صعود سريع جدًا، تحت 30 = هبوط سريع جدًا."],"c:Varning":["🏃‍♂️ العدّاء السريع لا يجب أن يتوقف فورًا.","🔥 التشبّع الشرائي لا يعني أن السعر يجب أن ينخفض الآن.","💪 في الاتجاهات القوية قد يبقى RSI مرتفعًا وقتًا طويلًا.","🧠 تذكّر: RSI مرتفع = كن حذرًا، وليس بيعًا تلقائيًا."],"c:1–2-procentsregeln":["🍬 تخيّل أن لديك 100 قطعة حلوى.","🎲 إذا راهنت بقطعة أو قطعتين فقط كل مرة، فسيبقى لديك الكثير حتى لو خسرت مرات كثيرة متتالية.","💥 أما إذا راهنت بـ 50 قطعة، فخسارتان تكفيان لضياع كل شيء تقريبًا.","🧠 تذكّر: خاطر بـ 1–2 بالمئة من الحساب على الأكثر في كل صفقة."],"c:Förluster är asymmetriska":["🍰 لديك كعكة. إذا اختفى نصفها، يبقى لديك نصف كعكة.","➕ لتعود الكعكة كاملة، يجب أن يتضاعف النصف. هذا يعني 100 بالمئة زيادة!","📉 إذن خسارة 50 بالمئة أسهل بكثير من استعادتها بعد ذلك.","🧠 تذكّر: احمِ مالك أولًا، لأن الخسائر الكبيرة صعبة التعويض."],"c:Positionsstorlek":["❓ حجم المركز يعني: كم سهمًا يجب أن أشتري؟","💰 أولًا تقرر كم أنت مستعد أن تخسر، مثلًا 100.","📏 ثم ترى كم المسافة إلى فرامل الطوارئ، مثلًا 2 لكل سهم.","➗ 100 مقسومة على 2 = 50 سهمًا. إذا عملت الفرامل، تخسر 100 فقط.","🧠 تذكّر: عدد الأسهم = المخاطرة بالمال ÷ المسافة إلى وقف الخسارة."],"c:Risk/reward":["⚖️ نسبة المخاطرة إلى العائد مثل الميزان. في كفة: ما قد تخسره. وفي الأخرى: ما قد تربحه.","🍬 تخاطر بقطعة حلوى واحدة لتربح 3. يُكتب ذلك 1:3.","✅ عندها يكفي أن تصيب مرة من كل 4 مرات تقريبًا لتتعادل، دون حساب الرسوم.","🧠 تذكّر: الربح الممكن يجب أن يكون أكبر من الخسارة الممكنة."],"c:FOMO":["😱 FOMO يعني الخوف من أن يفوتك شيء.","🎢 الجميع يتحدث عن سهم ارتفع بقوة، وتريد أنت أيضًا أن تقفز إليه.","🏔️ لكن الناس غالبًا يشترون حينها والسعر في القمة بالفعل.","🧘 من الأفضل أن تتبع خطتك. هناك دائمًا فرص أخرى.","🧠 تذكّر: لا تطارد، ستأتي حافلة أخرى."],"c:Hämndtrading":["😤 تداول الانتقام هو عندما تخسر وتغضب وتريد استعادة المال فورًا.","🎰 عندها تخاطر أكثر من المعتاد، مثل المراهنة بكل شيء دفعة واحدة.","📉 وغالبًا ينتهي ذلك بخسارة أكبر.","🧠 تذكّر: بعد الخسارة، خذ استراحة."],"c:Tradingplan":["🗺️ خطة التداول مثل الخريطة قبل الرحلة.","📝 تكتب مسبقًا: ماذا تشتري، ومتى تشتري، وأين فرامل الطوارئ، وكم تخاطر.","🧊 هكذا تقرر برأس هادئ بدل أن تقرر وأنت متوتر.","🧠 تذكّر: خطط أولًا، ثم تداول."],"c:Avgifter":["🧾 كل مرة تشتري أو تبيع، يكلفك ذلك قليلًا من المال. هذا اسمه العمولة.","↔️ الفارق بين سعر الشراء وسعر البيع يكلف أيضًا.","🔁 إذا تداولت كثيرًا، تتحول التكاليف الصغيرة إلى مبلغ كبير.","🧠 تذكّر: صفقات أكثر = رسوم أكثر."],"c:ISK":["🏦 ISK نوع من حسابات الادخار للأسهم والصناديق في السويد.","🧾 لا تدفع ضريبة كل مرة تربح فيها. بدلًا من ذلك تدفع ضريبة صغيرة كل سنة، محسوبة على المبلغ الموجود في الحساب.","🎁 منذ 2026، أول 300 000 كرونة معفاة من الضريبة، في المجموع لكل شخص. قد تتغير القواعد، فتحقق لدى مصلحة الضرائب السويدية.","🧠 تذكّر: ISK = ضريبة سنوية صغيرة بدل ضريبة على كل ربح."],"c:Varningstecken":["🚨 هل يعدك أحد بأنك ستصبح غنيًا بسرعة وبشكل مضمون؟ هذا احتيال في أغلب الأحيان.","⏰ هل يقول لك أحد إن عليك أن تسرع الآن؟ هذه حيلة كي لا يكون لديك وقت للتفكير.","💬 المجموعات في التطبيقات التي تطلب منك إرسال المال إليها احتيال شائع.","🔍 تحقق دائمًا من الشركة لدى الجهة الرقابية المالية.","🧠 تذكّر: مضمون + مستعجل = ابتعد."],"p:doji":["🕯️ انظر إلى الشمعة: الجسم يكاد يكون خطًا فقط.","🤝 انتهى السعر تقريبًا حيث بدأ. المشترون والبائعون شدّوا الحبل بالقوة نفسها.","⏸️ بعد حركة طويلة، قد يعني ذلك أن القوة بدأت تنفد.","🧠 تذكّر: الدوجي = تعادل، انتظر الشمعة التالية."],"p:dragonfly":["🪰 تبدو الشمعة مثل حرف T، مثل اليعسوب.","⬇️ دفع البائعون السعر إلى الأسفل كثيرًا.","⬆️ لكن المشترين أعادوه إلى الأعلى بالكامل قبل نهاية الفترة.","🧠 تذكّر: اليعسوب بعد هبوط قد يعني أن المشترين يستيقظون."],"p:gravestone":["🪦 تبدو الشمعة مثل حرف T مقلوب، مثل شاهد القبر.","⬆️ دفع المشترون السعر إلى الأعلى كثيرًا.","⬇️ لكن البائعين أعادوه إلى الأسفل بالكامل.","🧠 تذكّر: شاهد القبر بعد صعود تحذير من هبوط."],"p:longDoji":["🕯️ انظر: تقريبًا بلا جسم، لكن بفتائل طويلة جدًا في الاتجاهين.","🎢 صعد السعر كثيرًا ونزل كثيرًا، لكنه انتهى حيث بدأ.","🤷 لا أحد يعرف من سيفوز. حيرة كبيرة.","🧠 تذكّر: أرجل طويلة = ارتباك كبير، انتظر وراقب."],"p:spinning":["🌀 للبلبل جسم صغير في الوسط وفتائل في الاتجاهين.","🤝 لم يسيطر أي طرف في هذه الفترة.","⏸️ يظهر غالبًا عندما يأخذ الاتجاه استراحة.","🧠 تذكّر: البلبل = استراحة، انتظر الشمعة التالية."],"p:marubozuBull":["🟩 شمعة خضراء طويلة بلا أي فتائل.","🦸 سيطر المشترون من أول ثانية إلى آخر ثانية.","🚀 تظهر غالبًا في بداية الصعود.","🧠 تذكّر: أخضر بلا فتائل = المشترون مسيطرون تمامًا."],"p:marubozuBear":["🟥 شمعة حمراء طويلة بلا أي فتائل.","🦹 سيطر البائعون من أول ثانية إلى آخر ثانية.","📉 تظهر غالبًا في بداية الهبوط.","🧠 تذكّر: أحمر بلا فتائل = البائعون مسيطرون تمامًا."],"p:hammer":["🔨 تبدو الشمعة مثل مطرقة: جسم صغير في الأعلى ومقبض طويل إلى الأسفل.","⬇️ هبط السعر كثيرًا خلال الفترة.","⬆️ لكن المشترين قالوا لا ودفعوه إلى الأعلى.","📍 تكون أكثر أهمية بعد هبوط، عند أرضية.","🧠 تذكّر: المطرقة تضرب القاع، وربما يصعد السعر."],"p:invHammer":["🔨 مطرقة مقلوبة: جسم صغير في الأسفل وفتيل طويل إلى الأعلى.","⬆️ بعد هبوط، حاول المشترون دفع السعر إلى الأعلى.","🤔 لم ينجحوا تمامًا بعد، لذلك ننتظر شمعة خضراء قوية بعدها.","🧠 تذكّر: المطرقة المقلوبة = المشترون يجرّبون، انتظر التأكيد."],"p:hangingMan":["🧍 يشبه المطرقة تمامًا، لكنه يظهر بعد صعود.","⬇️ خلال الفترة، نجح البائعون في خفض السعر قليلًا.","⚠️ قد يكون أول علامة على أن الصعود بدأ يتعب.","🧠 تذكّر: نفس شكل المطرقة، لكن في القمة = تحذير."],"p:shootingStar":["🌠 الشهاب: جسم صغير في الأسفل وفتيل طويل إلى الأعلى، بعد صعود.","⬆️ طار السعر عاليًا خلال الفترة.","⬇️ لكن البائعين أعادوه إلى الأسفل، مثل نجم يسقط.","🧠 تذكّر: الشهاب في القمة = قد ينخفض السعر."],"p:bullEng":["🐟 شمعتان: أولًا حمراء صغيرة، ثم خضراء كبيرة.","🍽️ الخضراء كبيرة لدرجة أنها تبتلع الحمراء كلها، مثل سمكة كبيرة تأكل سمكة صغيرة.","💪 سيطر المشترون بعد البائعين.","🧠 تذكّر: خضراء كبيرة تأكل حمراء صغيرة بعد هبوط = انعكاس محتمل إلى الأعلى."],"p:bearEng":["🐟 شمعتان: أولًا خضراء صغيرة، ثم حمراء كبيرة.","🍽️ الحمراء تبتلع الخضراء كلها.","👎 سيطر البائعون بعد المشترين.","🧠 تذكّر: حمراء كبيرة تأكل خضراء صغيرة بعد صعود = انعكاس محتمل إلى الأسفل."],"p:piercing":["🔴 أولًا شمعة حمراء.","🟢 ثم خضراء تبدأ أدنى لكنها تصعد فوق منتصف الحمراء.","🗡️ إنها تخترقها، ومن هنا جاء الاسم.","🧠 تذكّر: خضراء تتجاوز نصف الحمراء = المشترون يعودون."],"p:darkCloud":["🟢 أولًا شمعة خضراء.","☁️ ثم حمراء تبدأ أعلى لكنها تهبط تحت منتصف الخضراء، مثل سحابة داكنة.","⚠️ بدأ البائعون يسيطرون بعد صعود.","🧠 تذكّر: حمراء تهبط تحت نصف الخضراء = الغيوم قادمة."],"p:bullHarami":["🤰 هارامي تعني الحامل باليابانية.","🔴 شمعة حمراء كبيرة، ثم خضراء صغيرة داخلها، مثل طفل في بطن أمه.","🐢 بدأ البائعون يفقدون قوتهم.","🧠 تذكّر: خضراء صغيرة داخل حمراء كبيرة = إشارة ضعيفة، انتظر التأكيد."],"p:bearHarami":["🤰 شمعة خضراء كبيرة، ثم حمراء صغيرة داخلها.","🐢 بدأ المشترون يفقدون قوتهم.","⚠️ الإشارة ضعيفة، لذلك ننتظر الشمعة التالية.","🧠 تذكّر: حمراء صغيرة داخل خضراء كبيرة = تحذير، انتظر التأكيد."],"p:tweezBot":["🥢 شمعتان لهما نفس أدنى سعر تمامًا، مثل طرفي الملقط.","🛡️ دافع المشترون عن الأرضية نفسها مرتين.","🧠 تذكّر: قاعان عند المستوى نفسه = أرضية قوية."],"p:tweezTop":["🥢 شمعتان لهما نفس أعلى سعر تمامًا.","🛡️ دافع البائعون عن السقف نفسه مرتين.","🧠 تذكّر: قمتان عند المستوى نفسه = سقف قوي."],"p:morningStar":["🌅 ثلاث شموع، مثل شروق الشمس.","🔴 أولًا حمراء كبيرة: الجو مظلم والسعر يهبط.","⭐ ثم شمعة صغيرة أدنى: يصبح كل شيء هادئًا.","🟢 وأخيرًا خضراء كبيرة تصعد عاليًا: الشمس تشرق!","🧠 تذكّر: نجمة الصباح = انتهى الليل، وقد يصعد السعر."],"p:eveningStar":["🌇 ثلاث شموع، مثل غروب الشمس.","🟢 أولًا خضراء كبيرة: إنه النهار والسعر يصعد.","⭐ ثم شمعة صغيرة أعلى: يصبح كل شيء هادئًا.","🔴 وأخيرًا حمراء كبيرة تهبط عميقًا: الشمس تغرب.","🧠 تذكّر: نجمة المساء = المساء قادم، وقد يهبط السعر."],"p:soldiers":["💂💂💂 ثلاث شموع خضراء كبيرة متتالية، مثل جنود يسيرون إلى الأعلى.","⬆️ كل شمعة تنتهي قرب أعلى نقطة لها.","💪 المشترون أقوياء.","⚠️ إذا كان السعر يصعد منذ وقت طويل جدًا، فقد يكونون متعبين.","🧠 تذكّر: ثلاثة جنود خضر = صعود قوي."],"p:crows":["🐦‍⬛🐦‍⬛🐦‍⬛ ثلاث شموع حمراء كبيرة متتالية، مثل غربان تطير إلى الأسفل.","⬇️ كل شمعة تنتهي قرب أدنى نقطة لها.","👎 البائعون أقوياء.","🧠 تذكّر: ثلاثة غربان سود = هبوط قوي."],"p:insideUp":["1️⃣ شمعة حمراء كبيرة.","2️⃣ شمعة خضراء صغيرة داخلها، هذه هي الهارامي.","3️⃣ شمعة خضراء ثالثة تُغلق أعلى من افتتاح الشمعة الأولى. هذا هو التأكيد!","🧠 تذكّر: هارامي + تأكيد = ثلاثة من الداخل صاعدة."],"p:insideDown":["1️⃣ شمعة خضراء كبيرة.","2️⃣ شمعة حمراء صغيرة داخلها، هارامي.","3️⃣ شمعة حمراء ثالثة تُغلق أدنى من افتتاح الشمعة الأولى. تأكد!","🧠 تذكّر: هارامي + تأكيد هابط = ثلاثة من الداخل هابطة."],"p:risingThree":["🟢 أولًا شمعة خضراء كبيرة.","😮‍💨 ثم ثلاث شموع حمراء صغيرة تبقى داخلها. يأخذ السعر استراحة، مثل عدّاء يلتقط أنفاسه.","🚀 وأخيرًا خضراء كبيرة جديدة تصل إلى قمة جديدة.","🧠 تذكّر: استراحة في الصعود، ثم يستمر."],"p:fallingThree":["🔴 أولًا شمعة حمراء كبيرة.","😮‍💨 ثم ثلاث شموع خضراء صغيرة داخلها. استراحة قصيرة.","📉 وأخيرًا حمراء كبيرة جديدة تصل إلى قاع جديد.","🧠 تذكّر: استراحة في الهبوط، ثم يستمر."]}};
